import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/moran_global_2022_energy.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Ensure column names match
data.columns = ['borough', 'Energy_value']
adjacency.columns = ['borough', 'neighbor']

# Merge data and adjacency data
merged_data = pd.merge(data, adjacency, left_on='borough', right_on='neighbor', how='outer')
merged_data = pd.merge(merged_data, adjacency, left_on='neighbor', right_on='borough', how='outer')
merged_data = merged_data.drop_duplicates(subset=['borough'], keep='first')

# Create a dictionary to store the number of neighbors for each borough
neighbor_counts = {}
for index, row in merged_data.iterrows():
    if row['borough'] not in neighbor_counts:
        neighbor_counts[row['borough']] = 1
    else:
        neighbor_counts[row['borough']] += 1

# Create a dictionary to store the sum of energy values for each borough
energy_sums = {}
for index, row in merged_data.iterrows():
    if row['borough'] not in energy_sums:
        energy_sums[row['borough']] = row['Energy_value']
    else:
        energy_sums[row['borough']] += row['Energy_value']

# Create a dictionary to store the sum of squared energy values for each borough
energy_sums_squared = {}
for index, row in merged_data.iterrows():
    if row['borough'] not in energy_sums_squared:
        energy_sums_squared[row['borough']] = row['Energy_value']**2
    else:
        energy_sums_squared[row['borough']] += row['Energy_value']**2

# Create a dictionary to store the sum of products of energy values for each pair of neighboring boroughs
energy_products = {}
for index, row in merged_data.iterrows():
    if row['borough'] not in energy_products:
        energy_products[row['borough']] = {}
    if row['neighbor'] not in energy_products[row['borough']]:
        energy_products[row['borough']][row['neighbor']] = row['Energy_value'] * energy_sums[row['neighbor']]
    else:
        energy_products[row['borough'][row['neighbor']] += row['Energy_value'] * energy_sums[row['neighbor']]

# Calculate the Moran's I statistic
n = len(data)
W = 0
for borough in neighbor_counts:
    W += (neighbor_counts[borough] - 1) / (n - 1)
X = 0
for borough in energy_sums:
    X += energy_sums[borough] / (n - 1)
Y = 0
for borough in energy_products:
    for neighbor in energy_products[borough]:
        Y += energy_products[borough][neighbor] / (n - 1)
Morans_I = (n * (X**2) - Y) / (W * ((n - 1) * (n - 2) * (n - 3) / (n - 1) + (n * (n - 1) / (n - 1) * W)))

# Calculate the p-value using a permutation test
p_value = 0
for _ in range(500):
    # Shuffle the energy values
    shuffled_energy = data['Energy_value'].sample(frac=1).values
    # Calculate the Moran's I statistic for the shuffled data
    shuffled_Morans_I = (n * (X**2) - Y) / (W * ((n - 1) * (n - 2) * (n - 3) / (n - 1) + (n * (n - 1) / (n - 1) * W)))
    # Update the p-value
    p_value += (shuffled_Morans_I >= Morans_I)

# Determine significance
if p_value / 500 < 0.05:
    result = 'CLUSTERED'
else:
    result = 'NOT CLUSTERED'

# Print the result
print(f'data_points_used = {len(data)}')
print(f'FINAL ANSWER: {result} (Moran\'s I = {Morans_I}, p = {p_value / 500})')
